    catalog.className='archive-groups';catalog.innerHTML=years.map(yr=>renderYearGroup(yr,groups[yr])).join('');
    document.querySelectorAll('[data-year-toggle]').forEach(btn=>btn.onclick=()=>{const target=btn.closest('.year-group');const panel=target.querySelector('.year-content');const wasOpen=target.classList.contains('is-open');document.querySelectorAll('.year-group').forEach(group=>{const p=group.querySelector('.year-content');group.classList.remove('is-open');group.querySelector('[data-year-toggle]').setAttribute('aria-expanded','false');group.querySelector('.year-symbol').textContent='+';p.style.maxHeight=p.scrollHeight+'px';requestAnimationFrame(()=>{p.style.maxHeight='0px';});});if(!wasOpen){target.classList.add('is-open');btn.setAttribute('aria-expanded','true');btn.querySelector('.year-symbol').textContent='−';panel.hidden=false;panel.style.maxHeight='0px';requestAnimationFrame(()=>{panel.style.maxHeight=panel.scrollHeight+'px';});}});
